One important design note: since browser extensions cannot spawn system processes directly, `background.js` communicates with a small HTTP API running on your local machine to execute commands. To prevent a compromised or spoofed Gradio page from becoming a remote shell, the extension only accepts messages from `localhost` and uses a predefined command table rather than allowing arbitrary shell input. You should adjust this command table to fit your specific application needs.

**manifest.json** (Note: I have converted the "smart quotes" from your snippet into standard straight quotes so the JSON will parse correctly):

```json
{
  "manifest_version": 2,
  "name": "Gradio Remote Interface Extension",
  "version": "1.0",
  "description": "Interface between Gradio app running in the browser and locally running Linux system",

  "background": {
    "scripts": ["background.js"]
  },

  "permissions": [
    "tabs",
    "webRequest",
    "webRequestBlocking",
    "http://localhost/",
    "https://localhost/"
  ],

  "browser_action": {
    "default_title": "Gradio Remote Interface",
    "default_icon": "icon.png",
    "default_popup": "popup.html"
  }
}
```

**background.js**

```javascript
// Background script: bridges messages from the Gradio page to a small
// local HTTP API that executes the commands.

const ALLOWED_ORIGINS = ["http://localhost", "https://localhost"];
const LOCAL_API = "http://localhost:7861";

// Explicit command table instead of arbitrary shell execution.
// Add whatever commands your Gradio app needs here.
const COMMANDS = {
  ping: async (args) => ({ pong: true, args }),
  listDir: async (args) => {
    const dir = args && args.path ? args.path : ".";
    return runCommand("ls", ["-la", dir]);
  },
  readFile: async (args) => runCommand("cat", [args.path]),
};

async function runCommand(command, args) {
  const response = await fetch(LOCAL_API + "/exec", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ command, args })
  });
  if (!response.ok) {
    throw new Error("Local API returned " + response.status);
  }
  return response.json();
}

let gradioTabs = new Set();

chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  if (tab.url && tab.url.startsWith("http://localhost")) {
    gradioTabs.add(tabId);
  } else {
    gradioTabs.delete(tabId);
  }
});

chrome.tabs.onRemoved.addListener((tabId) => gradioTabs.delete(tabId));

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  const origin = sender.origin || (sender.url && new URL(sender.url).origin);
  if (!origin || !ALLOWED_ORIGINS.includes(origin)) {
    sendResponse({ error: "Origin not allowed: " + origin });
    return false;
  }

  if (message && message.type === "getStatus") {
    sendResponse({ connectedTabs: [...gradioTabs] });
    return false;
  }

  const handler = COMMANDS[message && message.type];
  if (!handler) {
    sendResponse({ error: "Unknown command: " + (message && message.type) });
    return false;
  }

  handler(message.args)
    .then((result) => sendResponse({ ok: true, result }))
    .catch((err) => sendResponse({ ok: false, error: String(err) }));

  return true; // keep the message channel open for the async response
});
```

